using System;using System.Linq;using System.IO;using System.Reflection;using System.Collections.Generic;using UnityEditor;using UnityEngine;using Unity.Profiling;
public static class TreeInstancingTrial {
 static Dictionary<Material,Shader> originals=new Dictionary<Material,Shader>();static Dictionary<Shader,Shader> variants=new Dictionary<Shader,Shader>();static Camera camera;static Vector3 position;static Quaternion rotation;static bool background;static int rate,vsync,phase,lastFrame;static double start,tri,bat;static bool captured;static ProfilerRecorder batches,triangles,gpu;static List<float> times=new List<float>(),gpuTimes=new List<float>();static string csv="view,mode,frames,mean_ms,median_ms,p95_ms,gpu_ms,batches,triangles\n";static string[] modes={"Original","Instancing","OriginalRepeat","InstancingRepeat"};static Vector3[] positions={new Vector3(509.513f,2.235f,1248.762f),new Vector3(500,2.235f,1180),new Vector3(465,3,912)};static float[] yaws={180,180,270};
 public static object Run(){if(!EditorApplication.isPlaying)throw new Exception("Play Mode required");DisableDebugger();EditorApplication.isPaused=false;var mats=Terrain.activeTerrains.SelectMany(t=>t.terrainData.treePrototypes).SelectMany(p=>p.prefab.GetComponentsInChildren<MeshRenderer>(true)).SelectMany(r=>r.sharedMaterials).Where(m=>m&&m.HasProperty("_Color")&&m.shader.name.StartsWith("FoggyRoad/Optimization/Graph/")).Distinct().ToArray();foreach(var m in mats){var source=m.shader;if(!variants.ContainsKey(source)){string code=File.ReadAllText(AssetDatabase.GetAssetPath(source));if(!code.Contains("float4 _Color;"))throw new Exception("Expected color declaration");code=code.Replace("Shader \""+source.name+"\"","Shader \""+source.name+" Instancing Trial\"").Replace("float4 _Color;","").Replace("CBUFFER_START(UnityPerMaterial)","float4 _Color;\nCBUFFER_START(UnityPerMaterial)");var shader=ShaderUtil.CreateShaderAsset(code,false);shader.hideFlags=HideFlags.HideAndDontSave;if(ShaderUtil.ShaderHasError(shader))throw new Exception("Trial shader error "+source.name);variants[source]=shader;}originals[m]=source;}
 camera=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).First(c=>c.name=="Camera");position=camera.transform.position;rotation=camera.transform.rotation;background=Application.runInBackground;rate=Application.targetFrameRate;vsync=QualitySettings.vSyncCount;Application.runInBackground=true;Application.targetFrameRate=-1;QualitySettings.vSyncCount=0;batches=ProfilerRecorder.StartNew(ProfilerCategory.Render,"Batches Count",1);triangles=ProfilerRecorder.StartNew(ProfilerCategory.Render,"Triangles Count",1);gpu=ProfilerRecorder.StartNew(ProfilerCategory.Render,"GPU Frame Time",1);phase=-1;lastFrame=-1;EditorApplication.playModeStateChanged+=OnPlayState;Next();EditorApplication.update+=Tick;return "Started3 views x4 phases; "+mats.Length+" materials, "+variants.Count+" temporary shader variants";}
 static void DisableDebugger(){var w=EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.FrameDebuggerWindow"));w.GetType().GetMethod("DisableFrameDebugger",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(w,null);var game=EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView"));game.maximized=true;game.Focus();}
 static void Restore(){foreach(var p in originals)if(p.Key)p.Key.shader=p.Value;}
 static void OnPlayState(PlayModeStateChange s){if(s==PlayModeStateChange.ExitingPlayMode)Finish();}
 static void Finish(){EditorApplication.update-=Tick;EditorApplication.playModeStateChanged-=OnPlayState;Restore();if(camera)camera.transform.SetPositionAndRotation(position,rotation);Application.runInBackground=background;Application.targetFrameRate=rate;QualitySettings.vSyncCount=vsync;batches.Dispose();triangles.Dispose();gpu.Dispose();foreach(var s in variants.Values)if(s)UnityEngine.Object.DestroyImmediate(s);File.WriteAllText("Recovery/DrawCalls_20261107/TreeInstancingTrial.status","COMPLETE; original material shaders restored");}
 static void Next(){Restore();phase++;if(phase>=positions.Length*modes.Length){Finish();return;}if(modes[phase%4].StartsWith("Instancing"))foreach(var p in originals)p.Key.shader=variants[p.Value];camera.transform.SetPositionAndRotation(positions[phase/4],Quaternion.Euler(0,yaws[phase/4],0));times.Clear();gpuTimes.Clear();bat=tri=0;captured=false;start=EditorApplication.timeSinceStartup;File.WriteAllText("Recovery/DrawCalls_20261107/TreeInstancingTrial.status",phase/4+" "+modes[phase%4]);}
 static string N(double n){return n.ToString(System.Globalization.CultureInfo.InvariantCulture);}
 static void Tick(){try{if(!EditorApplication.isPlaying){Finish();return;}camera.transform.SetPositionAndRotation(positions[phase/4],Quaternion.Euler(0,yaws[phase/4],0));if(Time.frameCount==lastFrame)return;lastFrame=Time.frameCount;double elapsed=EditorApplication.timeSinceStartup-start;if(elapsed<8)return;if(!captured){ScreenCapture.CaptureScreenshot(Path.GetFullPath("Recovery/DrawCalls_20261107/VerifiedTreeTrial_"+(phase/4)+"_"+modes[phase%4]+".png"));captured=true;}if(elapsed<13){times.Add(Time.unscaledDeltaTime*1000);bat+=batches.LastValue;tri+=triangles.LastValue;if(gpu.Valid&&gpu.LastValue>0)gpuTimes.Add(gpu.LastValue/1000000f);return;}times.Sort();gpuTimes.Sort();int n=times.Count;if(n>0)csv+=String.Join(",",phase/4,modes[phase%4],n,N(times.Average()),N(times[n/2]),N(times[Math.Min(n-1,(int)(n*.95))]),gpuTimes.Count>0?N(gpuTimes[gpuTimes.Count/2]):"NA",N(bat/n),N(tri/n))+"\n";File.WriteAllText("Recovery/DrawCalls_20261107/TreeInstancingTrial.csv",csv);Next();}catch(Exception e){Finish();File.WriteAllText("Recovery/DrawCalls_20261107/TreeInstancingTrial.status","ERROR "+e);}}
}



